import sys, json

def solve(rowIndex):
    row = [1] * (rowIndex + 1)
    for i in range(2, rowIndex + 1):
        for j in range(i - 1, 0, -1):
            row[j] += row[j - 1]
    return row

if __name__ == '__main__':
    line = sys.stdin.read().strip()
    if line:
        try:
            rowIndex = int(line)
            print(json.dumps(solve(rowIndex)))
        except:
            print("[1]")
    else:
        print("[1]")

